command:
set -euo pipefail
git log --no-merges --format="@@@%H%x09%ad%x09%s" --date=short --name-only d33c62eebc48de5e8a65c50e057addf25f125c6b..51e7faddad943ab7727e407d008e474ec076566d |
awk '
function flush() {
  if (seen && prod && !tests) print header
}
function reset() {prod=tests=0}
BEGIN {reset()}
$0 ~ /^@@@/ {flush(); seen=1; header=substr($0,4); reset(); next}
NF == 0 {next}
$0 ~ /^(src|methods)\// {prod=1}
$0 ~ /^(tests|benchmarks)\// {tests=1}
END {flush()}
'

